namespace sv_65a2954eaab54003af283dde7c67a820.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;

    private readonly List<Notification> _notifications =
    [
        new(1, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
        new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)),
        new(3, "New feature available: dark mode.", DateTime.UtcNow.AddMinutes(-5)),
    ];

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        lock (_notifications)
        {
            // Simulate new notifications appearing over time
            if (Random.Shared.Next(3) == 0)
            {
                var n = new Notification(_nextId++, $"New event at {DateTime.UtcNow:HH:mm:ss}", DateTime.UtcNow);
                _notifications.Add(n);
            }

            var results = _notifications.Where(n => n.Timestamp > since).ToList();
            return Task.FromResult(results);
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> notifications = new();
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Restore from persisted state if available (avoids re-fetching after prerender)
        if (PersistedNotifications is not null)
        {
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationService.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var since = notifications.Count > 0
                    ? notifications.Max(n => n.Timestamp)
                    : DateTime.MinValue;

                var newer = await NotificationService.GetNotificationsSinceAsync(since);
                if (newer.Count > 0)
                {
                    notifications.AddRange(newer);
                    PersistedNotifications = notifications;
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

