@rendermode InteractiveServer
@implements IDisposable
@inject NotificationService NotificationService
@inject PersistentComponentState ApplicationState

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;

    protected override async Task OnInitializedAsync()
    {
        _persistSub = ApplicationState.RegisterOnPersisting(PersistNotifications);

        if (!ApplicationState.TryTakeFromJson<List<Notification>>("notifications", out var restored))
        {
            notifications = await NotificationService.GetNotificationsAsync();
        }
        else
        {
            notifications = restored!;
        }
    }

    private Task PersistNotifications()
    {
        ApplicationState.PersistAsJson("notifications", notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during prerender, so the polling
        // loop only starts once the page is live and interactive.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var since = notifications.Count > 0
                    ? notifications.Max(n => n.Timestamp)
                    : DateTime.MinValue;

                var newer = await NotificationService.GetNotificationsSinceAsync(since);
                if (newer.Count > 0)
                {
                    notifications.AddRange(newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _persistSub.Dispose();
    }
}

